<?php ui_header('Thông báo','Cập nhật trạng thái ứng tuyển, AI screening và hoạt động mạng lưới.'); ?><div class="row section"><span class="muted" data-unread-total><?= count(array_filter($data,function($n){return !$n['isRead'];})) ?> chưa đọc</span><button class="ghost" data-action="/notifications/read-all" data-method="PATCH" data-reload>Đánh dấu tất cả đã đọc</button></div><section class="panel section"><?php if(!$data): ?><div class="empty"><?= ui_icon('bell',40) ?><h2>Bạn đã xem hết thông báo</h2><p class="muted">Thông báo mới sẽ xuất hiện tại đây.</p></div><?php endif; ?><?php foreach($data as $n):$notificationIcon=in_array($n['type'],['CONNECTION','CONNECTION_REQUEST','CONNECTION_ACCEPTED'],true)?'users':(in_array($n['type'],['AI_SCREENING','AI_SCREENING_DONE'],true)?'sparkles':(($n['data']['toStatus']??'')==='INTERVIEW'?'clock':(in_array($n['data']['toStatus']??'',['OFFER','HIRED'],true)?'check':(($n['data']['toStatus']??'')==='REJECTED'?'close':'bell')))); ?><article data-notification-item="<?= e($n['id']) ?>" class="notification-item <?= !$n['isRead']?'unread':'' ?>"><div class="company-initial"><?= ui_icon($notificationIcon,20) ?></div><div><h3><?= e($n['title']) ?></h3><p><?= e($n['body']) ?></p><small class="muted"><?= e(date('d/m/Y H:i',strtotime($n['createdAt']))) ?></small><?php $target=!empty($n['data']['url'])?safe_url($n['data']['url']):(!empty($n['data']['applicationId'])?($user['role']==='CANDIDATE'?'/applications/':'/ai-score/').$n['data']['applicationId']:(!empty($n['data']['connectionId'])?'/network':(!empty($n['data']['postId'])?'/feed?post='.$n['data']['postId']:null)));if($target): ?><p><a class="button ghost" data-notification-link="<?= e($n['id']) ?>" href="<?= e($target) ?>"><?= $target==='/network'?'Đến Mạng lưới':'Xem chi tiết' ?></a></p><?php endif; ?></div><?php if(!$n['isRead']): ?><button class="ghost" data-action="/notifications/<?= e($n['id']) ?>/read" data-method="PATCH" data-reload aria-label="Đánh dấu đã đọc"><?= ui_icon('check',18) ?></button><?php endif; ?></article><?php endforeach; ?></section>